"""Decompose target skeleton graphs into minimal continuous contact trails."""
import math
import numpy as np
from scipy import ndimage as ndi
import build_paths as bp


def component_trails(mask):
    sk=bp.thin(mask)
    yy,xx=np.where(sk); pix=set(zip(yy.tolist(),xx.tolist()))
    G={p:[] for p in pix}
    for y,x in pix:
        for dy in (-1,0,1):
            for dx in (-1,0,1):
                if not(dy or dx) or (y+dy,x+dx) not in pix: continue
                if dy and dx and ((y+dy,x) in pix or (y,x+dx) in pix): continue
                G[(y,x)].append((y+dy,x+dx))
    deg={p:len(G[p]) for p in pix}
    key={p for p in pix if deg[p]!=2}
    if not key:
        root=min(pix)
        prev=None;cur=root;nxt=G[cur][0];route=[root,nxt];prev,cur=cur,nxt
        while cur!=root:
            choices=[w for w in G[cur] if w!=prev]
            if not choices:break
            nxt=choices[0];prev,cur=cur,nxt;route.append(cur)
        return [np.array([[x,y] for y,x in route],float)], {'nodes':1,'arcs':1,'odd':0}
    keymask=np.zeros(sk.shape,np.uint8)
    for y,x in key:keymask[y,x]=1
    clab,ncl=ndi.label(keymask,structure=np.ones((3,3),int))
    feat={};centers={}
    for i in range(1,ncl+1):
        pts=[p for p in key if clab[p]>0 and clab[p]==i]
        if not pts:continue
        for p in pts:feat[p]=i-1
        centers[i-1]=np.mean(np.array([[p[1],p[0]] for p in pts],float),axis=0)
    used=set();arcs=[]
    def ek(a,b): return tuple(sorted((a,b)))
    for p in key:
        for q in G[p]:
            e=ek(p,q)
            if e in used:continue
            if q in key and feat[q]==feat[p]:
                used.add(e);continue
            used.add(e); seq=[p,q];prev,cur=p,q
            while cur not in key:
                choices=[w for w in G[cur] if w!=prev]
                choices=[w for w in choices if ek(cur,w) not in used]
                if not choices:break
                nxt=choices[0];used.add(ek(cur,nxt));seq.append(nxt);prev,cur=cur,nxt
            if cur in key:
                arcs.append((feat[p],feat[cur],np.array([[x,y] for y,x in seq],float)))
    # Add any untouched closed cycles that are not attached to key pixels.
    if not arcs:
        root=min(pix);prev=None;cur=root;nxt=G[cur][0];seq=[root,nxt];prev,cur=cur,nxt
        while cur!=root:
